function upload(c,address,b){input(c,140,b,"declared RAM upload");host(c,"upload",[address,b.length]);for(let i=0;i<b.length;i++)c.known.set(address+i,b[i]);}
function known(c,address,length){return Buffer.from(Array.from({length},(_,i)=>c.known.get(address+i)??0));}
function readRam(c,address,length,label){const b=Buffer.alloc(length),reads=[];for(let i=0;i<length;i++){reads.push(host(c,"read8",[address+i],label+" byte"+i));b[i]=arena(c).readUInt32LE(120);assert.deepEqual(arena(c).subarray(100,140),record("R3MH",40,[0,b[i],0,0,0,1],2));}
assert.deepEqual(b,known(c,address,length),label+" independent uploaded/stored bytes");const row={context:c.ordinal,owner:c.owner,label,address,bytes:length,hex:b.toString("hex"),reads};ram.push(row);return row;}
